"use client"

import { FormEvent, useEffect, useState } from "react"
import { ArrowRight, Calendar, CheckCircle, Mail, MessageCircle, ShieldAlert } from "lucide-react"
import { SiWhatsapp } from "react-icons/si"
import { Button } from "@/components/ui/button"
import { Container } from "@/components/ui/container"
import { Wrapper } from "@/components/ui/wrapper"
import { Breadcrumb } from "@/components/ui/breadcrumb"
import { SectionBadge } from "@/components/ui/section-badge"
import { FadeIn } from "@/components/ui/fade-in"
import { BOOKING_URL, WHATSAPP_URL } from "@/lib/constants"
import { trackLeadEvent } from "@/hooks/use-cookie-consent"

const inquiryTypes = [
  "New AI / Automation Project",
  "Partnership Opportunity",
  "Custom Software / SaaS",
  "Integration / Technical Project",
  "Existing Client Support",
  "General Inquiry",
]

const companyTypes = [
  "Business Consultancy",
  "ERP / CRM Implementation Firm",
  "IT Services / MSP",
  "Digital Transformation Firm",
  "Software Company",
  "Business Setup / Corporate Services",
  "Specialist Consultancy",
  "Other",
]

const partnershipInterests = [
  "I have a client opportunity now",
  "Referral partnership",
  "Co-selling",
  "Co-delivery",
  "White-label delivery",
  "Exploring collaboration",
]

const toolOptions = ["CRM", "ERP", "WhatsApp", "Messenger", "Email", "Sheets", "Accounting", "Other"]

const fieldClass =
  "mt-2 min-h-11 w-full rounded-md border border-border bg-background px-3 py-2 text-sm text-foreground shadow-sm outline-none transition-colors placeholder:text-muted-foreground/70 focus:border-primary focus:ring-2 focus:ring-primary/15"

function pushInquiryEvent(event: string, details?: Record<string, string>) {
  if (typeof window !== "undefined" && window.dataLayer) {
    window.dataLayer.push({ event, ...details })
  }
}

export function InquiryPage() {
  const [inquiryType, setInquiryType] = useState("")
  const [partnershipInterest, setPartnershipInterest] = useState("")
  const [selectedTools, setSelectedTools] = useState<string[]>([])
  const [prepared, setPrepared] = useState(false)
  const isPartnership = inquiryType === "Partnership Opportunity"
  const hasClientOpportunity = partnershipInterest === "I have a client opportunity now"

  const emailAddress = "contact@arboraistudio.com"

  useEffect(() => {
    const searchParams = new URLSearchParams(window.location.search)
    if (searchParams.get("type") === "partnership") {
      setInquiryType("Partnership Opportunity")
    }
    if (searchParams.get("intent") === "opportunity") {
      setPartnershipInterest("I have a client opportunity now")
    }
  }, [])

  function toggleTool(tool: string) {
    setSelectedTools((current) => current.includes(tool) ? current.filter((item) => item !== tool) : [...current, tool])
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const line = (label: string, value: FormDataEntryValue | null) => `${label}: ${String(value || "Not provided")}`
    const body = [
      line("Inquiry type", form.get("inquiryType")),
      line("Name", form.get("name")),
      line("Work email", form.get("email")),
      line("Company", form.get("company")),
      line("Country / region", form.get("region")),
      line("Phone / WhatsApp", form.get("phone")),
      line("Timeline", form.get("timeline")),
      `Tools currently involved: ${selectedTools.length ? selectedTools.join(", ") : "Not provided"}`,
      "",
      "What we are trying to improve:",
      String(form.get("improvement") || ""),
      "",
      "How it works today:",
      String(form.get("currentProcess") || "Not provided"),
    ]

    if (isPartnership) {
      body.push(
        "",
        line("Partner company type", form.get("companyType")),
        line("Preferred partnership model", form.get("partnershipInterest")),
      )
      if (hasClientOpportunity) {
        body.push("", "Client problem (no confidential details):", String(form.get("clientProblem") || ""))
      }
    }

    const subject = `[Website inquiry] ${inquiryType || "General inquiry"}`
    const mailto = `mailto:${emailAddress}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body.join("\n"))}`
    pushInquiryEvent("inquiry_email_prepare", { inquiry_type: inquiryType || "unknown" })
    setPrepared(true)
    window.location.href = mailto
  }

  return (
    <div className="pb-20 pt-24">
      <Wrapper>
        <Container>
          <div className="mb-8"><Breadcrumb items={[{ label: "Contact" }]} /></div>
          <FadeIn className="mb-12 max-w-3xl">
            <SectionBadge title="Tell Us What You Are Working On" className="mb-5" />
            <h1 className="text-4xl font-bold leading-tight md:text-5xl">What Are You Trying to Improve?</h1>
            <p className="mt-5 text-lg leading-relaxed text-muted-foreground">
              Whether you have a defined project or a workflow that keeps wasting time, tell us what happens today. We will review the context and tell you whether Arbor is a realistic fit.
            </p>
          </FadeIn>

          <div className="grid gap-12 lg:grid-cols-[minmax(0,1.25fr)_minmax(300px,0.75fr)] lg:gap-16">
            <FadeIn>
              <form className="space-y-7" onSubmit={handleSubmit}>
                <div>
                  <label className="text-sm font-semibold" htmlFor="inquiry-type">Inquiry type *</label>
                  <select className={fieldClass} id="inquiry-type" name="inquiryType" onChange={(event) => setInquiryType(event.target.value)} required value={inquiryType}>
                    <option value="">Select an inquiry type</option>
                    {inquiryTypes.map((option) => <option key={option}>{option}</option>)}
                  </select>
                </div>

                <div className="grid gap-5 sm:grid-cols-2">
                  <div>
                    <label className="text-sm font-semibold" htmlFor="inquiry-name">Name *</label>
                    <input autoComplete="name" className={fieldClass} id="inquiry-name" name="name" required />
                  </div>
                  <div>
                    <label className="text-sm font-semibold" htmlFor="inquiry-email">Work email *</label>
                    <input autoComplete="email" className={fieldClass} id="inquiry-email" name="email" required type="email" />
                  </div>
                  <div>
                    <label className="text-sm font-semibold" htmlFor="inquiry-company">Company</label>
                    <input autoComplete="organization" className={fieldClass} id="inquiry-company" name="company" />
                  </div>
                  <div>
                    <label className="text-sm font-semibold" htmlFor="inquiry-region">Country / region</label>
                    <input autoComplete="country-name" className={fieldClass} id="inquiry-region" name="region" />
                  </div>
                  <div className="sm:col-span-2">
                    <label className="text-sm font-semibold" htmlFor="inquiry-phone">Phone / WhatsApp <span className="font-normal text-muted-foreground">(optional)</span></label>
                    <input autoComplete="tel" className={fieldClass} id="inquiry-phone" name="phone" type="tel" />
                  </div>
                </div>

                <div>
                  <label className="text-sm font-semibold" htmlFor="inquiry-improvement">What are you trying to improve? *</label>
                  <textarea className={`${fieldClass} min-h-28 resize-y`} id="inquiry-improvement" name="improvement" placeholder="We receive 100+ enquiries every day and manually copy qualified leads into our CRM." required />
                </div>

                <div>
                  <label className="text-sm font-semibold" htmlFor="inquiry-current-process">Tell us how it works today</label>
                  <textarea className={`${fieldClass} min-h-32 resize-y`} id="inquiry-current-process" name="currentProcess" placeholder="What happens now? Which tools are involved? Where does the process slow down? What would a better outcome look like?" />
                </div>

                <fieldset>
                  <legend className="text-sm font-semibold">Tools currently involved</legend>
                  <div className="mt-3 flex flex-wrap gap-2">
                    {toolOptions.map((tool) => {
                      const selected = selectedTools.includes(tool)
                      return (
                        <label className={`cursor-pointer rounded-md border px-3 py-2 text-sm transition-colors ${selected ? "border-primary bg-primary/5 text-foreground" : "border-border text-muted-foreground hover:border-primary/40"}`} key={tool}>
                          <input checked={selected} className="sr-only" onChange={() => toggleTool(tool)} type="checkbox" />
                          {tool}
                        </label>
                      )
                    })}
                  </div>
                </fieldset>

                <div>
                  <label className="text-sm font-semibold" htmlFor="inquiry-timeline">Timeline</label>
                  <select className={fieldClass} id="inquiry-timeline" name="timeline">
                    <option value="">Select a timeline</option>
                    <option>Exploring</option><option>Within 1 month</option><option>1–3 months</option><option>3+ months</option>
                  </select>
                </div>

                {isPartnership && (
                  <fieldset className="space-y-6 border-l-2 border-primary/25 pl-5">
                    <legend className="mb-4 text-sm font-semibold text-primary">Partnership details</legend>
                    <div>
                      <label className="text-sm font-semibold" htmlFor="inquiry-company-type">What type of company are you?</label>
                      <select className={fieldClass} id="inquiry-company-type" name="companyType">
                        <option value="">Select a company type</option>
                        {companyTypes.map((option) => <option key={option}>{option}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="text-sm font-semibold" htmlFor="inquiry-partnership-interest">How would you like to work with Arbor?</label>
                      <select className={fieldClass} id="inquiry-partnership-interest" name="partnershipInterest" onChange={(event) => setPartnershipInterest(event.target.value)} value={partnershipInterest}>
                        <option value="">Select an option</option>
                        {partnershipInterests.map((option) => <option key={option}>{option}</option>)}
                      </select>
                    </div>
                    {hasClientOpportunity && (
                      <div>
                        <label className="text-sm font-semibold" htmlFor="inquiry-client-problem">Briefly describe the client problem</label>
                        <textarea className={`${fieldClass} min-h-28 resize-y`} id="inquiry-client-problem" name="clientProblem" placeholder="Do not include the client name or confidential information." />
                      </div>
                    )}
                  </fieldset>
                )}

                <div className="flex items-start gap-3 border-y border-border/70 py-4 text-sm text-muted-foreground">
                  <ShieldAlert className="mt-0.5 h-5 w-5 shrink-0 text-primary" aria-hidden="true" />
                  <p>Do not include passwords, API keys, confidential customer information, or regulated personal data. This form prepares an email in your own email app; the website does not store the form contents.</p>
                </div>

                <Button className="h-12 w-full gap-2 sm:w-auto" size="lg" type="submit">
                  Prepare Inquiry Email <ArrowRight className="h-4 w-4" />
                </Button>
                {prepared && <p className="text-sm text-primary" role="status">Your email app should now be open with the inquiry details prepared for review.</p>}
              </form>
            </FadeIn>

            <aside className="space-y-10">
              <FadeIn>
                <h2 className="text-2xl font-bold">Prefer Another Route?</h2>
                <div className="mt-5 divide-y divide-border/70 border-y border-border/70">
                  <a className="flex gap-3 py-5 hover:text-primary" href={`mailto:${emailAddress}`} onClick={() => trackLeadEvent({ source: "inquiry_direct_email" })}>
                    <Mail className="mt-0.5 h-5 w-5 shrink-0 text-primary" /><span><strong className="block">Email Arbor</strong><span className="text-sm text-muted-foreground">{emailAddress}</span></span>
                  </a>
                  <a className="flex gap-3 py-5 hover:text-primary" href={WHATSAPP_URL} onClick={() => trackLeadEvent({ source: "inquiry_whatsapp" })} rel="noopener noreferrer" target="_blank">
                    <SiWhatsapp className="mt-0.5 h-5 w-5 shrink-0 text-[#25D366]" /><span><strong className="block">WhatsApp Arbor</strong><span className="text-sm text-muted-foreground">For a quick initial question</span></span>
                  </a>
                  <a className="flex gap-3 py-5 hover:text-primary" href={BOOKING_URL} onClick={() => trackLeadEvent({ source: "inquiry_booking" })} rel="noopener noreferrer" target="_blank">
                    <Calendar className="mt-0.5 h-5 w-5 shrink-0 text-primary" /><span><strong className="block">Workflow Fit Call</strong><span className="text-sm text-muted-foreground">When you already know which workflow to discuss</span></span>
                  </a>
                </div>
              </FadeIn>

              <FadeIn>
                <div className="flex items-center gap-3"><MessageCircle className="h-5 w-5 text-primary" /><h2 className="text-2xl font-bold">What Happens Next?</h2></div>
                <ol className="mt-6 space-y-5 border-l border-primary/25 pl-6">
                  {["A person reviews the business problem and context.", "We route it to project, technical, partnership, or support review.", "We ask for missing information only where required.", "If there is a fit, we discuss discovery and scoping."].map((step, index) => (
                    <li className="relative text-sm leading-relaxed text-muted-foreground" key={step}>
                      <span className="absolute -left-[31px] top-1 h-3 w-3 rounded-full border-2 border-primary bg-background" />
                      <strong className="block text-foreground">{String(index + 1).padStart(2, "0")}</strong>{step}
                    </li>
                  ))}
                </ol>
                <p className="mt-6 flex gap-2 text-sm font-medium"><CheckCircle className="h-5 w-5 shrink-0 text-primary" />No pitch deck or technical specification required. Start with the problem.</p>
              </FadeIn>
            </aside>
          </div>
        </Container>
      </Wrapper>
    </div>
  )
}
